ALTER TABLE public.worlds ADD COLUMN npc_tax_rates jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE FUNCTION public.protect_npc_tax_rates() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NEW.npc_tax_rates IS DISTINCT FROM OLD.npc_tax_rates AND NOT public.is_world_owner(auth.uid(),NEW.id) THEN RAISE EXCEPTION 'Only the world owner can set NPC taxes'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_npc_tax_rates BEFORE UPDATE ON public.worlds FOR EACH ROW EXECUTE FUNCTION public.protect_npc_tax_rates();
CREATE FUNCTION public.get_world_tax_policies(_world_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE rates jsonb; w worlds%ROWTYPE; i integer; BEGIN IF auth.uid() IS NULL OR NOT is_world_member(auth.uid(),_world_id) THEN RAISE EXCEPTION 'Not a world member'; END IF; SELECT * INTO w FROM worlds WHERE id=_world_id; SELECT COALESCE(jsonb_object_agg(user_id::text,LEAST(100,GREATEST(0,COALESCE((player_data->'sovereignty'->>'taxRate')::numeric,0)))),'{}'::jsonb) INTO rates FROM world_members WHERE world_id=_world_id AND player_data->'sovereignty'->>'name' IS NOT NULL; IF w.enable_npcs THEN FOR i IN 0..w.npc_count-1 LOOP rates:=jsonb_set(rates,ARRAY['npc-'||i],to_jsonb(LEAST(100,GREATEST(0,COALESCE((w.npc_tax_rates->>('npc-'||i))::numeric,10))))); END LOOP; END IF; RETURN rates; END $$;
CREATE FUNCTION public.assess_citizen_tax(_citizen jsonb,_prior jsonb,_day bigint,_rate numeric) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE c jsonb:=_citizen; owner text:=_citizen->'allegiance'->>'userId'; old_owner text:=_prior->'allegiance'->>'userId'; last_day bigint; mood_day bigint; days bigint; cycles bigint; money numeric:=GREATEST(0,COALESCE((_citizen->>'coins')::numeric,0)); mood numeric:=LEAST(100,GREATEST(0,COALESCE((_citizen->>'happiness')::numeric,50))); paid numeric:=0; amount numeric; unhappy bigint; rate numeric:=LEAST(100,GREATEST(0,COALESCE(_rate,0))); BEGIN c:=jsonb_set(c,'{coins}',to_jsonb(money)); IF owner IS NULL OR _rate IS NULL THEN RETURN jsonb_build_object('citizen',c,'paid',0); END IF; IF owner IS DISTINCT FROM old_owner OR _prior->>'lastTaxDay' IS NULL THEN last_day:=_day; mood_day:=_day; unhappy:=0; ELSE last_day:=LEAST(_day,(_prior->>'lastTaxDay')::bigint); mood_day:=LEAST(_day,COALESCE((_prior->>'taxMoodDay')::bigint,_day)); unhappy:=COALESCE((_prior->>'taxUnhappyDays')::bigint,0); END IF; cycles:=(_day-last_day)/28; WHILE cycles>0 LOOP amount:=floor(money*rate/100); money:=money-amount; paid:=paid+amount; last_day:=last_day+28; cycles:=cycles-1; EXIT WHEN money=0; END LOOP; last_day:=last_day+((_day-last_day)/28)*28; days:=_day-mood_day; mood:=GREATEST(0,mood-days*GREATEST(0,ceil((rate-10)/10))); IF rate>=50 THEN unhappy:=unhappy+days; ELSE unhappy:=0; END IF; c:=c||jsonb_build_object('coins',money,'lastTaxDay',last_day,'taxMoodDay',_day,'taxUnhappyDays',unhappy,'happiness',mood,'lastTaxPaid',CASE WHEN paid>0 THEN paid ELSE COALESCE((_prior->>'lastTaxPaid')::numeric,0) END); IF rate>=50 AND mood<=20 AND unhappy>=7 THEN c:=(c-'allegiance'-'buildingKey'-'partnerId')||jsonb_build_object('taxExileUntilDay',_day+28,'taxUnhappyDays',0); END IF; RETURN jsonb_build_object('citizen',c,'paid',paid); END $$;
CREATE OR REPLACE FUNCTION public.save_world_citizens(_world_id uuid,_revision bigint,_strangers jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w worlds%ROWTYPE; old_citizens jsonb; current_revision bigint; old_by_id jsonb; rates jsonb; c jsonb; prior jsonb; result jsonb; new_citizens jsonb:='[]'; treasury jsonb:='{}'; owner text; paid bigint; day bigint; r record; changed boolean:=false; BEGIN IF auth.uid() IS NULL OR NOT is_world_member(auth.uid(),_world_id) THEN RAISE EXCEPTION 'Not a world member'; END IF; IF _strangers IS NULL OR jsonb_typeof(_strangers)<>'array' THEN RAISE EXCEPTION 'Citizens must be an array'; END IF; SELECT * INTO w FROM worlds WHERE id=_world_id FOR UPDATE; SELECT strangers,revision INTO old_citizens,current_revision FROM world_citizens WHERE world_id=_world_id FOR UPDATE; IF current_revision IS DISTINCT FROM _revision THEN RETURN jsonb_build_object('saved',false,'strangers',old_citizens,'revision',current_revision); END IF; day:=GREATEST(0,floor(extract(epoch FROM(now()-w.created_at))/3600)); rates:=get_world_tax_policies(_world_id); SELECT COALESCE(jsonb_object_agg(value->>'id',value),'{}') INTO old_by_id FROM jsonb_array_elements(COALESCE(old_citizens,'[]')); FOR c IN SELECT value FROM jsonb_array_elements(_strangers) LOOP prior:=old_by_id->(c->>'id'); owner:=c->'allegiance'->>'userId'; result:=assess_citizen_tax(c,prior,day,(rates->>owner)::numeric); new_citizens:=new_citizens||jsonb_build_array(result->'citizen'); paid:=(result->>'paid')::bigint; IF paid>0 THEN treasury:=jsonb_set(treasury,ARRAY[owner],to_jsonb(COALESCE((treasury->>owner)::bigint,0)+paid)); END IF; IF result->'citizen' IS DISTINCT FROM c THEN changed:=true; END IF; END LOOP; FOR r IN SELECT key,value FROM jsonb_each_text(treasury) ORDER BY key LOOP IF r.key LIKE 'npc-%' THEN w.npc_land_trade_coins:=jsonb_set(w.npc_land_trade_coins,ARRAY[r.key],to_jsonb(COALESCE((w.npc_land_trade_coins->>r.key)::bigint,0)+r.value::bigint)); ELSE UPDATE world_members SET land_trade_coins=land_trade_coins+r.value::bigint WHERE world_id=_world_id AND user_id=r.key::uuid; END IF; END LOOP; IF treasury<>'{}' THEN UPDATE worlds SET npc_land_trade_coins=w.npc_land_trade_coins WHERE id=_world_id; END IF; UPDATE world_citizens SET strangers=new_citizens,revision=revision+1 WHERE world_id=_world_id; RETURN jsonb_build_object('saved',true,'strangers',new_citizens,'revision',current_revision+1,'economyChanged',changed,'treasuryChanged',treasury<>'{}'); END $$;
REVOKE EXECUTE ON FUNCTION public.get_world_tax_policies(uuid),public.assess_citizen_tax(jsonb,jsonb,bigint,numeric),public.protect_npc_tax_rates() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_world_tax_policies(uuid) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.assess_citizen_tax(jsonb,jsonb,bigint,numeric) TO service_role;
COMMENT ON FUNCTION public.assess_citizen_tax(jsonb,jsonb,bigint,numeric) IS '28-game-day percentage tax on citizen savings; daily happiness pressure above 10 percent; excessive rates at 50 percent or above can end pledges after seven days of pressure.';